// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes calldata ancillaryData) public {
        vm.assume(identifier != bytes32(0));
        vm.assume(time <= type(uint64).max);

        int256 price = c.getPrice(identifier, time, ancillaryData);
        assertTrue(price == int256(0));
    }
}
